import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        sc.close();
        long[] dp = new long[n];
        dp[0] = 1;

        for (int i = 0; i < n; i++) {
            if (dp[i] > 0) {
                for (int j = 1; i + a[i] * j < n; j++) {
                    dp[i + a[i] * j] = (dp[i + a[i] * j] + dp[i]) % MOD;
                }
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = (ans + dp[i]) % MOD;
        }

        System.out.println(ans);
    }
}
